def compute(vars):
    due_fiscal_2019 = vars["v1"] + vars["v2"]
    total_commitments = vars["v3"] + vars["v4"]
    if total_commitments == 0:
        return None
    value = due_fiscal_2019 / total_commitments
    return {
        "value": value,
        "trace": {
            "due_fiscal_2019": due_fiscal_2019,
            "total_commitments": total_commitments,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
